export const STYLE_CSS = ":root {\n  --bg-primary: #0b0f19;\n  --bg-secondary: #111827;\n  --bg-card: #1f2937;\n  --bg-card-hover: #283548;\n  --border-color: #374151;\n  --text-main: #f9fafb;\n  --text-muted: #9ca3af;\n  --text-sub: #6b7280;\n\n  --critical: #ef4444;\n  --critical-bg: rgba(239, 68, 68, 0.12);\n  --critical-border: rgba(239, 68, 68, 0.35);\n\n  --high: #f97316;\n  --high-bg: rgba(249, 115, 22, 0.12);\n  --high-border: rgba(249, 115, 22, 0.35);\n\n  --medium: #eab308;\n  --medium-bg: rgba(234, 179, 8, 0.12);\n  --medium-border: rgba(234, 179, 8, 0.35);\n\n  --success: #10b981;\n  --success-bg: rgba(16, 185, 129, 0.12);\n  --success-border: rgba(16, 185, 129, 0.35);\n\n  --accent: #6366f1;\n  --accent-hover: #4f46e5;\n  --accent-glow: rgba(99, 102, 241, 0.25);\n\n  --ai-purple: #a855f7;\n  --ai-purple-bg: rgba(168, 85, 247, 0.1);\n  --ai-purple-border: rgba(168, 85, 247, 0.3);\n\n  --radius-sm: 6px;\n  --radius-md: 10px;\n  --radius-lg: 14px;\n  --shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.4);\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;\n  background-color: var(--bg-primary);\n  color: var(--text-main);\n  line-height: 1.5;\n  min-height: 100vh;\n}\n\n/* Header */\n.navbar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 1rem 2rem;\n  background-color: rgba(17, 24, 39, 0.85);\n  backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--border-color);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n}\n\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n}\n\n.brand-icon {\n  width: 36px;\n  height: 36px;\n  background: linear-gradient(135deg, var(--accent), var(--ai-purple));\n  border-radius: var(--radius-sm);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.25rem;\n  box-shadow: 0 0 15px var(--accent-glow);\n}\n\n.brand-title {\n  font-size: 1.15rem;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n}\n\n.brand-subtitle {\n  font-size: 0.75rem;\n  color: var(--text-muted);\n}\n\n.nav-actions {\n  display: flex;\n  gap: 0.75rem;\n  align-items: center;\n}\n\n.live-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-size: 0.75rem;\n  color: var(--success);\n  background: var(--success-bg);\n  border: 1px solid var(--success-border);\n  padding: 0.25rem 0.65rem;\n  border-radius: 9999px;\n  font-weight: 600;\n}\n\n.pulse-dot {\n  width: 7px;\n  height: 7px;\n  background-color: var(--success);\n  border-radius: 50%;\n  animation: pulse 2s infinite;\n}\n\n@keyframes pulse {\n  0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.7); }\n  70% { transform: scale(1); box-shadow: 0 0 0 6px rgba(16, 185, 129, 0); }\n  100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); }\n}\n\n/* Container */\n.container {\n  max-width: 1400px;\n  margin: 0 auto;\n  padding: 1.75rem 2rem;\n}\n\n/* Metrics Grid */\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 1.25rem;\n  margin-bottom: 2rem;\n}\n\n.stat-card {\n  background: var(--bg-secondary);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  padding: 1.25rem;\n  box-shadow: var(--shadow);\n  display: flex;\n  flex-direction: column;\n  transition: transform 0.2s ease, border-color 0.2s ease;\n}\n\n.stat-card:hover {\n  transform: translateY(-2px);\n  border-color: var(--accent);\n}\n\n.stat-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  color: var(--text-muted);\n  font-size: 0.85rem;\n  font-weight: 500;\n  margin-bottom: 0.5rem;\n}\n\n.stat-value {\n  font-size: 2rem;\n  font-weight: 700;\n  color: var(--text-main);\n  letter-spacing: -0.03em;\n}\n\n.stat-desc {\n  font-size: 0.75rem;\n  color: var(--text-sub);\n  margin-top: 0.35rem;\n}\n\n.stat-critical { border-left: 4px solid var(--critical); }\n.stat-active   { border-left: 4px solid var(--high); }\n.stat-total    { border-left: 4px solid var(--accent); }\n.stat-latency  { border-left: 4px solid var(--medium); }\n\n/* Main Content Layout */\n.layout-grid {\n  display: grid;\n  grid-template-columns: 1fr 380px;\n  gap: 1.75rem;\n}\n\n@media (max-width: 1080px) {\n  .layout-grid {\n    grid-template-columns: 1fr;\n  }\n}\n\n/* Section Containers */\n.section-card {\n  background: var(--bg-secondary);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  padding: 1.5rem;\n  margin-bottom: 1.75rem;\n  box-shadow: var(--shadow);\n}\n\n.section-title-bar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 1.25rem;\n  flex-wrap: wrap;\n  gap: 0.75rem;\n}\n\n.section-title {\n  font-size: 1.15rem;\n  font-weight: 600;\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n/* Filter Controls */\n.filter-tabs {\n  display: flex;\n  gap: 0.5rem;\n  flex-wrap: wrap;\n}\n\n.filter-btn {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  color: var(--text-muted);\n  padding: 0.35rem 0.75rem;\n  border-radius: var(--radius-sm);\n  font-size: 0.8rem;\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.filter-btn:hover, .filter-btn.active {\n  background: var(--accent);\n  color: #fff;\n  border-color: var(--accent);\n}\n\n/* Alert Feed */\n.alert-feed {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n}\n\n.empty-state {\n  text-align: center;\n  padding: 3rem 1rem;\n  color: var(--text-muted);\n}\n\n.empty-state svg {\n  width: 48px;\n  height: 48px;\n  stroke: var(--text-sub);\n  margin-bottom: 0.75rem;\n}\n\n.alert-card {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  padding: 1.25rem;\n  position: relative;\n  transition: border-color 0.2s ease;\n}\n\n.alert-card.CRITICAL {\n  border-left: 4px solid var(--critical);\n}\n\n.alert-card.HIGH {\n  border-left: 4px solid var(--high);\n}\n\n.alert-card.MEDIUM {\n  border-left: 4px solid var(--medium);\n}\n\n.alert-card.resolved {\n  opacity: 0.65;\n  border-left: 4px solid var(--success);\n}\n\n.alert-card-top {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  margin-bottom: 0.75rem;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n}\n\n.alert-header-info {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  flex-wrap: wrap;\n}\n\n.badge {\n  font-size: 0.7rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  padding: 0.2rem 0.5rem;\n  border-radius: var(--radius-sm);\n  letter-spacing: 0.05em;\n}\n\n.badge-CRITICAL {\n  background: var(--critical-bg);\n  color: var(--critical);\n  border: 1px solid var(--critical-border);\n}\n\n.badge-HIGH {\n  background: var(--high-bg);\n  color: var(--high);\n  border: 1px solid var(--high-border);\n}\n\n.badge-MEDIUM {\n  background: var(--medium-bg);\n  color: var(--medium);\n  border: 1px solid var(--medium-border);\n}\n\n.badge-resolved {\n  background: var(--success-bg);\n  color: var(--success);\n  border: 1px solid var(--success-border);\n}\n\n.api-badge {\n  background: rgba(255, 255, 255, 0.07);\n  color: var(--text-main);\n  font-family: monospace;\n  font-size: 0.8rem;\n  padding: 0.2rem 0.5rem;\n  border-radius: var(--radius-sm);\n}\n\n.alert-time {\n  font-size: 0.75rem;\n  color: var(--text-sub);\n}\n\n.alert-headline {\n  font-size: 1rem;\n  font-weight: 600;\n  margin-bottom: 0.5rem;\n  color: var(--text-main);\n}\n\n/* AI Diagnostic Block */\n.ai-diagnosis-box {\n  background: var(--ai-purple-bg);\n  border: 1px solid var(--ai-purple-border);\n  border-radius: var(--radius-sm);\n  padding: 0.85rem 1rem;\n  margin-top: 0.75rem;\n}\n\n.ai-header {\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-size: 0.75rem;\n  font-weight: 700;\n  color: var(--ai-purple);\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  margin-bottom: 0.4rem;\n}\n\n.ai-content {\n  font-size: 0.85rem;\n  color: #e2e8f0;\n  margin-bottom: 0.5rem;\n}\n\n.ai-action {\n  font-size: 0.85rem;\n  color: #a5f3fc;\n  border-top: 1px dashed rgba(168, 85, 247, 0.3);\n  padding-top: 0.4rem;\n}\n\n.alert-actions-bar {\n  display: flex;\n  justify-content: flex-end;\n  gap: 0.5rem;\n  margin-top: 0.75rem;\n}\n\n.btn {\n  padding: 0.4rem 0.85rem;\n  border-radius: var(--radius-sm);\n  font-size: 0.8rem;\n  font-weight: 600;\n  cursor: pointer;\n  border: 1px solid transparent;\n  transition: all 0.2s ease;\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n}\n\n.btn-primary {\n  background: var(--accent);\n  color: #fff;\n}\n.btn-primary:hover {\n  background: var(--accent-hover);\n}\n\n.btn-secondary {\n  background: var(--bg-card-hover);\n  border-color: var(--border-color);\n  color: var(--text-main);\n}\n.btn-secondary:hover {\n  background: #374151;\n}\n\n.btn-resolve {\n  background: var(--success-bg);\n  border-color: var(--success-border);\n  color: var(--success);\n}\n.btn-resolve:hover {\n  background: var(--success);\n  color: #fff;\n}\n\n/* API Table */\n.table-container {\n  overflow-x: auto;\n}\n\ntable {\n  width: 100%;\n  border-collapse: collapse;\n  text-align: left;\n  font-size: 0.85rem;\n}\n\nth {\n  padding: 0.75rem 1rem;\n  background: rgba(255, 255, 255, 0.02);\n  color: var(--text-muted);\n  font-weight: 600;\n  border-bottom: 1px solid var(--border-color);\n}\n\ntd {\n  padding: 0.75rem 1rem;\n  border-bottom: 1px solid var(--border-color);\n  color: var(--text-main);\n}\n\ntr:hover td {\n  background: rgba(255, 255, 255, 0.03);\n}\n\n/* Simulator Form */\n.simulator-form {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n}\n\n.preset-buttons {\n  display: flex;\n  flex-direction: column;\n  gap: 0.5rem;\n  margin-bottom: 1rem;\n}\n\n.preset-btn {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  color: var(--text-main);\n  padding: 0.6rem 0.75rem;\n  border-radius: var(--radius-sm);\n  font-size: 0.8rem;\n  text-align: left;\n  cursor: pointer;\n  transition: all 0.2s ease;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.preset-btn:hover {\n  background: var(--bg-card-hover);\n  border-color: var(--accent);\n}\n\n.form-group {\n  display: flex;\n  flex-direction: column;\n  gap: 0.35rem;\n}\n\n.form-group label {\n  font-size: 0.8rem;\n  color: var(--text-muted);\n  font-weight: 500;\n}\n\n.form-control {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  color: var(--text-main);\n  padding: 0.5rem 0.75rem;\n  border-radius: var(--radius-sm);\n  font-size: 0.85rem;\n  outline: none;\n  font-family: inherit;\n}\n\n.form-control:focus {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 2px var(--accent-glow);\n}\n\n.toast {\n  position: fixed;\n  bottom: 2rem;\n  right: 2rem;\n  padding: 0.85rem 1.25rem;\n  background: var(--bg-card);\n  border: 1px solid var(--accent);\n  border-radius: var(--radius-md);\n  color: #fff;\n  box-shadow: var(--shadow);\n  display: none;\n  z-index: 1000;\n  font-size: 0.85rem;\n  animation: slideIn 0.3s ease;\n}\n\n@keyframes slideIn {\n  from { transform: translateY(20px); opacity: 0; }\n  to { transform: translateY(0); opacity: 1; }\n}\n";
export const APP_JS = "let currentFilter = 'all';\n\n// Presets data\nconst PRESETS = {\n  healthy: { api_name: 'PatientDataAPI', status_code: 200, response_time_ms: 180, records_returned: 45 },\n  crash: { api_name: 'AppointmentAPI', status_code: 500, response_time_ms: 320, records_returned: 0 },\n  timeout: { api_name: 'CaregiverDispatchAPI', status_code: 504, response_time_ms: 6200, records_returned: 0 },\n  empty: { api_name: 'MedicationScheduleAPI', status_code: 200, response_time_ms: 210, records_returned: 0 },\n  auth: { api_name: 'AuthTokenService', status_code: 401, response_time_ms: 95, records_returned: 0 },\n  latency: { api_name: 'BillingServiceAPI', status_code: 200, response_time_ms: 5200, records_returned: 85 },\n};\n\ndocument.addEventListener('DOMContentLoaded', () => {\n  setupEventListeners();\n  loadDashboardData();\n  // Poll every 10 seconds for live updates\n  setInterval(loadDashboardData, 10000);\n});\n\nfunction setupEventListeners() {\n  // Refresh button\n  document.getElementById('btn-refresh').addEventListener('click', () => {\n    loadDashboardData();\n    showToast('Telemetry refreshed.');\n  });\n\n  // Batch run button\n  document.getElementById('btn-batch-run').addEventListener('click', async () => {\n    try {\n      showToast('Running batch evaluation on sample dataset...');\n      // Sample batch data\n      const samplePayload = [\n        { api_name: 'PatientDataAPI', response_time_ms: 180, status_code: 200, records_returned: 45 },\n        { api_name: 'AppointmentAPI', response_time_ms: 5500, status_code: 500, records_returned: 0 },\n        { api_name: 'BillingServiceAPI', response_time_ms: 3200, status_code: 200, records_returned: 120 },\n        { api_name: 'MedicationScheduleAPI', response_time_ms: 210, status_code: 200, records_returned: 0 },\n        { api_name: 'CaregiverDispatchAPI', response_time_ms: 6200, status_code: 504, records_returned: 0 },\n        { api_name: 'AuthTokenService', response_time_ms: 95, status_code: 401, records_returned: 0 },\n        { api_name: 'HealthRecordsSyncAPI', response_time_ms: 340, status_code: 200, records_returned: 18 },\n      ];\n\n      const res = await fetch('/monitor', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(samplePayload),\n      });\n      const data = await res.json();\n      showToast(`Batch completed: ${data.data.anomalies_detected} anomalies recorded.`);\n      loadDashboardData();\n    } catch (err) {\n      showToast(`Batch run failed: ${err.message}`);\n    }\n  });\n\n  // Filter tabs\n  const filterBtns = document.querySelectorAll('.filter-btn');\n  filterBtns.forEach((btn) => {\n    btn.addEventListener('click', () => {\n      filterBtns.forEach((b) => b.classList.remove('active'));\n      btn.classList.add('active');\n      currentFilter = btn.dataset.filter;\n      loadAlerts();\n    });\n  });\n\n  // Preset buttons\n  const presetBtns = document.querySelectorAll('.preset-btn');\n  presetBtns.forEach((btn) => {\n    btn.addEventListener('click', () => {\n      const presetKey = btn.dataset.preset;\n      const data = PRESETS[presetKey];\n      if (data) {\n        document.getElementById('input-api-name').value = data.api_name;\n        document.getElementById('input-status-code').value = data.status_code;\n        document.getElementById('input-latency').value = data.response_time_ms;\n        document.getElementById('input-records').value = data.records_returned;\n        showToast(`Loaded preset: ${presetKey}`);\n      }\n    });\n  });\n\n  // Ingestion form submit\n  const form = document.getElementById('simulator-form');\n  form.addEventListener('submit', async (e) => {\n    e.preventDefault();\n    const payload = {\n      api_name: document.getElementById('input-api-name').value.trim(),\n      status_code: parseInt(document.getElementById('input-status-code').value, 10),\n      response_time_ms: parseInt(document.getElementById('input-latency').value, 10),\n      records_returned: parseInt(document.getElementById('input-records').value, 10),\n    };\n\n    try {\n      const res = await fetch('/monitor', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(payload),\n      });\n      const result = await res.json();\n      if (result.success) {\n        if (result.data.has_anomaly) {\n          showToast(`⚠️ Anomaly detected for ${payload.api_name}!`);\n        } else {\n          showToast(`✅ Operational telemetry recorded for ${payload.api_name}.`);\n        }\n        loadDashboardData();\n      } else {\n        showToast(`Error: ${result.error}`);\n      }\n    } catch (err) {\n      showToast(`Ingestion failed: ${err.message}`);\n    }\n  });\n}\n\nasync function loadDashboardData() {\n  await Promise.all([loadMetricsSummary(), loadAlerts()]);\n}\n\nasync function loadMetricsSummary() {\n  try {\n    const res = await fetch('/metrics/summary');\n    const json = await res.json();\n    if (!json.success) return;\n\n    const s = json.data;\n    document.getElementById('stat-total-calls').textContent = s.totalCalls.toLocaleString();\n    document.getElementById('stat-critical-count').textContent = s.criticalAnomalies.toLocaleString();\n    document.getElementById('stat-active-count').textContent = s.activeAnomalies.toLocaleString();\n    document.getElementById('stat-avg-latency').textContent = `${s.avgResponseTime} ms`;\n\n    // Render API Table\n    const tbody = document.getElementById('api-table-body');\n    if (!s.apis || s.apis.length === 0) {\n      tbody.innerHTML = `<tr><td colspan=\"6\" style=\"text-align: center; color: var(--text-muted);\">No endpoint telemetry recorded yet. Run a batch or send a metric!</td></tr>`;\n      return;\n    }\n\n    tbody.innerHTML = s.apis\n      .map((api) => {\n        const isProblem = api.anomaly_count > 0;\n        const statusBadge = isProblem\n          ? `<span class=\"badge badge-CRITICAL\">Degraded</span>`\n          : `<span class=\"badge badge-resolved\">Healthy</span>`;\n\n        return `\n        <tr>\n          <td><strong style=\"color: #fff;\">${escapeHtml(api.api_name)}</strong></td>\n          <td>${api.total_requests}</td>\n          <td>\n            <span style=\"color: ${api.success_rate < 90 ? 'var(--critical)' : 'var(--success)'}; font-weight: 600;\">\n              ${api.success_rate}%\n            </span>\n          </td>\n          <td>${api.avg_latency_ms} ms</td>\n          <td>\n            <span style=\"color: ${api.anomaly_count > 0 ? 'var(--critical)' : 'var(--text-muted)'}; font-weight: 600;\">\n              ${api.anomaly_count}\n            </span>\n          </td>\n          <td>${statusBadge}</td>\n        </tr>\n      `;\n      })\n      .join('');\n  } catch (err) {\n    console.error('Error fetching metrics summary:', err);\n  }\n}\n\nasync function loadAlerts() {\n  const container = document.getElementById('alerts-container');\n  try {\n    let url = '/alerts?limit=50';\n    if (currentFilter === 'active') {\n      url += '&status=active';\n    } else if (currentFilter === 'resolved') {\n      url += '&status=resolved';\n    } else if (['CRITICAL', 'HIGH', 'MEDIUM'].includes(currentFilter)) {\n      url += `&severity=${currentFilter}`;\n    }\n\n    const res = await fetch(url);\n    const json = await res.json();\n    if (!json.success) return;\n\n    const alerts = json.data;\n    if (alerts.length === 0) {\n      container.innerHTML = `\n        <div class=\"empty-state\">\n          <div style=\"font-size: 2rem; margin-bottom: 0.5rem;\">🎉</div>\n          <div style=\"font-weight: 600;\">No alerts matching filter \"${currentFilter}\"</div>\n          <div style=\"font-size: 0.8rem; margin-top: 0.25rem;\">Everything is operating within healthy parameters.</div>\n        </div>\n      `;\n      return;\n    }\n\n    container.innerHTML = alerts\n      .map((alert) => {\n        const isResolved = alert.status === 'resolved';\n        return `\n        <div class=\"alert-card ${alert.severity} ${isResolved ? 'resolved' : ''}\" id=\"alert-card-${alert.id}\">\n          <div class=\"alert-card-top\">\n            <div class=\"alert-header-info\">\n              <span class=\"badge badge-${alert.severity}\">${alert.severity}</span>\n              <span class=\"badge ${isResolved ? 'badge-resolved' : 'badge-HIGH'}\">${alert.status.toUpperCase()}</span>\n              <span class=\"api-badge\">${escapeHtml(alert.api_name)}</span>\n              <span class=\"alert-time\">${formatDate(alert.created_at)}</span>\n            </div>\n            ${\n              !isResolved\n                ? `<button class=\"btn btn-resolve\" onclick=\"resolveAlert(${alert.id})\">✔ Resolve Alert</button>`\n                : `<span style=\"font-size: 0.75rem; color: var(--success); font-weight: 600;\">Resolved</span>`\n            }\n          </div>\n\n          <div class=\"alert-headline\">${escapeHtml(alert.ai_alert)}</div>\n          \n          <div style=\"font-size: 0.8rem; color: var(--text-muted); margin-bottom: 0.5rem;\">\n            <strong>Detected Trigger:</strong> ${escapeHtml(alert.description)}\n          </div>\n\n          <div class=\"ai-diagnosis-box\">\n            <div class=\"ai-header\">\n              <span>🤖 AI Diagnostic Root Cause</span>\n            </div>\n            <div class=\"ai-content\">\n              ${escapeHtml(alert.ai_analysis || 'No detailed analysis generated.')}\n            </div>\n            <div class=\"ai-action\">\n              <strong>💡 Suggested Action:</strong> ${escapeHtml(alert.suggested_action || 'Review API logs.')}\n            </div>\n          </div>\n        </div>\n      `;\n      })\n      .join('');\n  } catch (err) {\n    container.innerHTML = `<div class=\"empty-state\" style=\"color: var(--critical);\">Failed to load alerts: ${err.message}</div>`;\n  }\n}\n\nwindow.resolveAlert = async function (id) {\n  try {\n    const res = await fetch(`/alerts/${id}/resolve`, { method: 'PATCH' });\n    const json = await res.json();\n    if (json.success) {\n      showToast(`Alert #${id} marked as resolved!`);\n      loadDashboardData();\n    } else {\n      showToast(`Error: ${json.error}`);\n    }\n  } catch (err) {\n    showToast(`Failed to resolve alert: ${err.message}`);\n  }\n};\n\nfunction formatDate(dateStr) {\n  if (!dateStr) return '';\n  const d = new Date(dateStr);\n  return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });\n}\n\nfunction escapeHtml(str) {\n  if (!str) return '';\n  return String(str)\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;')\n    .replace(/'/g, '&#039;');\n}\n\nlet toastTimer;\nfunction showToast(msg) {\n  const toast = document.getElementById('toast');\n  toast.textContent = msg;\n  toast.style.display = 'block';\n  clearTimeout(toastTimer);\n  toastTimer = setTimeout(() => {\n    toast.style.display = 'none';\n  }, 3500);\n}\n";
